\begin{aligned}
\frac{C_{\mathrm{H}_{2}}}{C_{\mathrm{N}_{2}}}=\sqrt{7} &=\sqrt{\frac{T_{\mathrm{H}_{2}} \times 28}{2 \times T_{\mathrm{N}_{2}}}} \\
7 &=\frac{14 T_{\mathrm{H}_{2}}}{T_{\mathrm{N}_{2}}} \\
